import {mergeGeometries} from 'three/addons/utils/BufferGeometryUtils.js';
import {buildCloudBase} from '../island-connections/cloud-base.js';
import {CLOUD_COLORS} from '../island-connections/layout.js';
import{airportCamera,airportSpawn}from'./airport-space.js';
import*as T from'three';import{createPlaneView}from'./plane-view.js';import{AIRPORT_SHORE}from'./layout.js';
export function buildAirportView(def,{integrated=false,planeFactory=createPlaneView}={}){const root=new T.Group();root.name=def.id;const geometries=new Set(),materials=new Map(),boxGeometry=new T.BoxGeometry(1,1,1);geometries.add(boxGeometry);let disposed=false;const mat=c=>{if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:.95}));return materials.get(c);};const box=(name,x,y,z,w,h,d,c)=>{const mesh=new T.Mesh(boxGeometry,mat(c));mesh.name='airport.'+name;mesh.position.set(x,y,z);mesh.scale.set(w,h,d);mesh.castShadow=mesh.receiveShadow=true;root.add(mesh);return mesh;};
 const land=new T.Group();land.name='airport.land';root.add(land);const tile=(name,x0,x1,z0,z1,color='#cad8be')=>{const mesh=box(name,(x0+x1)/2,-.20,(z0+z1)/2,x1-x0,.5,z1-z0,color);land.add(mesh);return mesh;};
 if(!integrated){
 // Disjoint top faces share y=.05: the runway is not a raised slab buried through the wheels.
 tile('runway',-3.8,3.8,-12,12,'#dad9cc');tile('land.north',-3.8,3.8,-17,-12);tile('land.south',-3.8,3.8,12,17);tile('land.east',3.8,6,-17,17);tile('land.west',-12.8,-11.25,-17,17);tile('land.apron',-9.75,-3.8,-17,17);tile('land.path-north',-11.25,-9.75,-17,5.15);tile('land.path-south',-11.25,-9.75,15.65,17);tile('waiting-path',-11.25,-9.75,5.15,15.65,'#f1e3c8');
 // The core stays exact; a coplanar organic ring extends the same walkable polygon.
 const coastShape=new T.Shape(AIRPORT_SHORE.map(([x,z])=>new T.Vector2(x,-z))),hole=new T.Path([[-12.8,-17],[6,-17],[6,17],[-12.8,17]].map(([x,z])=>new T.Vector2(x,-z)));coastShape.holes.push(hole);const coastGeometry=new T.ShapeGeometry(coastShape);coastGeometry.rotateX(-Math.PI/2);geometries.add(coastGeometry);const coast=new T.Mesh(coastGeometry,mat('#cad8be'));coast.name='airport.coast-top';coast.position.y=.05;coast.receiveShadow=true;land.add(coast);
 const skirtVertices=[],skirtIndices=[],levels=[[0,.05],[.08,-.015],[.20,-.22],[.03,-.48]],center=new T.Vector2(-3.4,0);for(const[offset,y]of levels)for(const[x,z]of AIRPORT_SHORE){const normal=new T.Vector2(x-center.x,z-center.y).normalize();skirtVertices.push(x+normal.x*offset,y,z+normal.y*offset);}for(let layer=0;layer<levels.length-1;layer++)for(let i=0;i<AIRPORT_SHORE.length;i++){const n=AIRPORT_SHORE.length,j=(i+1)%n,a=layer*n+i,b=layer*n+j,c=a+n,d=b+n;skirtIndices.push(a,c,b,b,c,d);}const skirtGeometry=new T.BufferGeometry();skirtGeometry.setAttribute('position',new T.Float32BufferAttribute(skirtVertices,3));skirtGeometry.setIndex(skirtIndices);skirtGeometry.computeVertexNormals();geometries.add(skirtGeometry);const skirt=new T.Mesh(skirtGeometry,mat('#eadbbf'));skirt.name='airport.soft-shore';root.add(skirt);
 }else{
  const top=(name,x0,x1,z0,z1,color)=>{const geo=new T.PlaneGeometry(x1-x0,z1-z0);geo.rotateX(-Math.PI/2);geometries.add(geo);const mesh=new T.Mesh(geo,mat(color));mesh.name='airport.'+name;mesh.position.set((x0+x1)/2,.05,(z0+z1)/2);mesh.receiveShadow=true;land.add(mesh);};
  top('runway',-3.8,3.8,-12,12,'#dad9cc');top('waiting-path',-11.25,-9.75,5.15,15.65,'#f1e3c8');
 }
 const marker=new T.Object3D(),dashes=new T.InstancedMesh(boxGeometry,mat('#f9efd6'),10);dashes.name='airport.runway.dashes';root.add(dashes);for(let i=0;i<10;i++){marker.position.set(0,.0505,-9+i*2);marker.scale.set(.14,.0002,.74);marker.updateMatrix();dashes.setMatrixAt(i,marker.matrix);}
 const marks=new T.InstancedMesh(boxGeometry,mat('#f9efd6'),10);marks.name='airport.thresholds';root.add(marks);let n=0;for(const z of[-10.95,10.95])for(const x of[-2,-1,0,1,2]){marker.position.set(x,.0505,z);marker.scale.set(.32,.0002,.75);marker.updateMatrix();marks.setMatrixAt(n++,marker.matrix);}
 // The narrow taxi paint is an emitted continuous curve, with actual geometry available to QA.
 const points=[new T.Vector3(-5,.068,8),new T.Vector3(-5,.068,-10)];for(let i=1;i<=40;i++){const a=Math.PI+i*Math.PI/40;points.push(new T.Vector3(-2.5+2.5*Math.cos(a),.068,-10+2.5*Math.sin(a)));}const lineVertices=[],lineIndices=[];for(let i=0;i<points.length;i++){const prior=points[Math.max(0,i-1)],next=points[Math.min(points.length-1,i+1)],dx=next.x-prior.x,dz=next.z-prior.z,len=Math.hypot(dx,dz),nx=-dz/len*.026,nz=dx/len*.026;lineVertices.push(points[i].x+nx,.0505,points[i].z+nz,points[i].x-nx,.0505,points[i].z-nz);if(i){const a=(i-1)*2,b=i*2;lineIndices.push(a,b,a+1,a+1,b,b+1);}}const lineGeometry=new T.BufferGeometry();lineGeometry.setAttribute('position',new T.Float32BufferAttribute(lineVertices,3));lineGeometry.setIndex(lineIndices);lineGeometry.computeVertexNormals();geometries.add(lineGeometry);const line=new T.Mesh(lineGeometry,mat('#d9b770'));line.name='airport.taxi-line';root.add(line);
 box('safety-paint',-8.9,.0505,0,.045,.0002,31.5,'#d9b770');for(const[x,z]of(integrated?[-12.65].flatMap(x=>[10,12.8].map(z=>[x,z])):[-11.6,-9.4].flatMap(x=>[10,12.8].map(z=>[x,z]))))box(`post.${x}.${z}`,x,1.38,z,.14,2.66,.14,'#cba989');if(integrated)for(const z of[10,12.8])box('cantilever.'+z,-12.135,2.66,z,1.17,.12,.14,'#cba989');box('waiting-roof',-10.5,2.79,11.4,2.4,.14,3.05,def.id==='villageAirport'?'#a9cbbd':CLOUD_COLORS.roof);box('waiting-bench',integrated?-11.77:-11.27,.41,11.4,.49,.20,1.75,'#f1e3c8');
 const windsock=new T.Group();windsock.name='airport.windsock';root.add(windsock);const poleGeometry=new T.CylinderGeometry(.032,.040,2,10);geometries.add(poleGeometry);const pole=new T.Mesh(poleGeometry,mat('#cba989'));pole.name='airport.windsock.pole';pole.position.set(-11.85,1.05,8.3);windsock.add(pole);for(let i=0;i<3;i++){const g=new T.CylinderGeometry(.14-.024*(i+1),.14-.024*i,.23,12,1,true);geometries.add(g);const cloth=new T.Mesh(g,mat(i%2?'#f9efd6':'#d9b770'));cloth.name='airport.windsock.stripe.'+i;cloth.rotation.z=-Math.PI/2;cloth.position.set(-11.85+.115+.23*i,2.07-.03*i,8.3);windsock.add(cloth);}const signX=integrated?-12.65:-10.5,sign=box('identity',signX,2.18,12.91,1.22,.67,.06,'#f1e3c8');box('identity.fuselage',signX,2.18,12.95,.075,.41,.025,def.id==='villageAirport'?'#a9cbbd':CLOUD_COLORS.roof);box('identity.wings',signX,2.17,12.95,.61,.08,.025,def.id==='villageAirport'?'#a9cbbd':CLOUD_COLORS.roof);box('identity.tail',signX,2.03,12.95,.25,.055,.025,def.id==='villageAirport'?'#a9cbbd':CLOUD_COLORS.roof);
 // This roof belongs to this airport. Cut it only when it crosses the actual rider's view rays.
 const shelterRoof=root.getObjectByName('airport.waiting-roof'),roofBox=new T.Box3(new T.Vector3(-.5,-.5,-.5),new T.Vector3(.5,.5,.5)),roofInverse=new T.Matrix4(),visibilityRay=new T.Ray(),visibilityDirection=new T.Vector3(),visibilityHit=new T.Vector3();shelterRoof.updateMatrix();
 function updateVisibility(camera,position){if(disposed||!camera||!position)return;if(integrated){shelterRoof.updateWorldMatrix(true,false);const roofWorld=new T.Box3().setFromObject(shelterRoof);roofWorld.min.x-=.85;roofWorld.max.x+=.85;roofWorld.min.z-=.85;roofWorld.max.z+=.85;roofWorld.min.y-=1.9;visibilityRay.origin.set(position.x,position.y??.05,position.z);camera.getWorldDirection(visibilityRay.direction).negate();shelterRoof.visible=!visibilityRay.intersectBox(roofWorld,visibilityHit);return;}root.updateWorldMatrix(true,false);roofInverse.copy(root.matrixWorld).multiply(shelterRoof.matrix).invert();camera.getWorldDirection(visibilityDirection).negate().transformDirection(roofInverse);visibilityRay.direction.copy(visibilityDirection);let obstructed=false;for(const x of[-.55,0,.55])for(const y of[.2,.9,1.65])for(const z of[-.4,0,.4]){visibilityRay.origin.set(position.x+x,position.y+y,position.z+z).applyMatrix4(roofInverse);if(visibilityRay.intersectBox(roofBox,visibilityHit))obstructed=true;}shelterRoof.visible=!obstructed;}
 const cloudBase=integrated?null:buildCloudBase(def.id,AIRPORT_SHORE);if(cloudBase){root.add(cloudBase);cloudBase.traverse(n=>{if(n.geometry)geometries.add(n.geometry);if(n.material)materials.set(n.material.uuid,n.material);});}
 const parked=planeFactory();parked.setFrame(def.endpoint.park);root.add(parked.root);if(integrated){const batches=new Map(),old=[];root.updateMatrixWorld(true);root.traverse(n=>{if(!n.isMesh||n.isInstancedMesh||n===shelterRoof||n.name==='airport.runway')return;for(let p=n;p;p=p.parent)if(p===parked.root)return;const g=n.geometry.index?n.geometry.toNonIndexed():n.geometry.clone();g.applyMatrix4(n.matrixWorld);const key=n.material.uuid+'|'+Object.keys(g.attributes).sort().join(',');if(!batches.has(key))batches.set(key,{material:n.material,parts:[]});batches.get(key).parts.push(g);old.push(n);});for(const n of old)n.removeFromParent();for(const{material,parts}of batches.values()){const g=mergeGeometries(parts),mesh=new T.Mesh(g,material);geometries.add(g);mesh.name='airport.static.batch';mesh.receiveShadow=mesh.castShadow=true;root.add(mesh);parts.forEach(p=>p.dispose());}}root.updateMatrixWorld(true);return{root,worldId:def.id,resolveSpawn:spawn=>airportSpawn(root,spawn),stars:[],occluders:[],updateVisibility,get camera(){return airportCamera(def.camera,root);},sync(){},animate(){},setActivityProgress(){},airport:{get ready(){return!disposed&&parked.root.parent===root&&!!root.getObjectByName('airport.runway');},parked,setParkedVisible(value){parked.root.visible=Boolean(value);}},dispose(){if(disposed)return;disposed=true;parked.dispose();for(const g of geometries)g.dispose();for(const m of materials.values())m.dispose();root.removeFromParent();root.clear();}};
}
